mapper.select:
SELECT s.schedule_id, s.hall_id, s.movie_id, s.schedule_startTime, 
       s.schedule_price, s.schedule_remain, s.schedule_state
FROM schedule s
INNER JOIN hall h ON s.hall_id = h.hall_id
WHERE h.cinema_id = #{cinemaId} 
AND s.movie_id = #{movieId} 
AND s.hall_id = #{hallId}
AND s.schedule_state = 1
ORDER BY s.schedule_startTime

mapper.update:
UPDATE schedule 
SET schedule_remain = schedule_remain + 1 
WHERE schedule_id = #{scheduleId}

UPDATE schedule 
SET schedule_remain = schedule_remain - 1 
WHERE schedule_id = #{scheduleId}
